// Pull normalized Earnings snapshots from the PICC connector registry and
// aggregate them into one list. Every connector emits the same shape, so the
// list is trivially comparable across api/ws/browser transports.

const base = $json.baseUrl || 'http://localhost:5173';
const token = $json.token || null;
const slugs = Array.isArray($json.slugs) ? $json.slugs : ['expertoption','honeygain','earnapp','grass','gradient','opensea','aave','yearn'];

const headers = { 'Content-Type': 'application/json' };
if (token) headers['Authorization'] = `Bearer ${token}`;

const rows = await Promise.all(slugs.map(async (slug) => {
  try {
    const r = await fetch(`${base}/api/connectors/${encodeURIComponent(slug)}/collect`, {
      method: 'POST',
      headers,
      body: '{}',
      signal: AbortSignal.timeout(60000)
    });
    const d = await r.json();
    return {
      provider: d.provider ?? slug,
      platform: d.platform ?? slug,
      balance: d.balance ?? null,
      today: d.today ?? null,
      lifetime: d.lifetime ?? null,
      payoutThreshold: d.payoutThreshold ?? null,
      estimatedDaily: d.estimatedDaily ?? null,
      currency: d.currency ?? 'USD',
      source: d.source ?? 'unknown',
      status: d.status ?? 'error',
      error: d.error ?? null,
      lastChecked: d.lastChecked ?? null
    };
  } catch (e) {
    return { provider: slug, platform: slug, status: 'error', error: e.message, lastChecked: null };
  }
}));

const okRows = rows.filter((r) => r.status === 'ok' && (r.balance != null || r.lifetime != null));
const totalBalance = okRows.reduce((s, r) => s + (Number(r.balance) || 0), 0);
const totalToday = okRows.reduce((s, r) => s + (Number(r.today) || 0), 0);
const totalLifetime = okRows.reduce((s, r) => s + (Number(r.lifetime) || 0), 0);

return [{
  json: {
    userId: $json.userId ?? null,
    timestamp: new Date().toISOString(),
    streams: rows,
    totals: { balance: totalBalance, today: totalToday, lifetime: totalLifetime },
    count: rows.length
  }
}];

